cd /tmp && python3 - <<'EOF'
import json, collections
meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l)
    meds[m['id']]=m
def mname(m):
    c=m.get('code',{})
    t=c.get('text')
    if t: return t
    for cc in c.get('coding',[]):
        if cc.get('display'): return cc['display']
    return None
import re
pat=re.compile(r'warfarin|apixaban|rivaroxaban|dabigatran|edoxaban|coumadin|citalopram|escitalopram|haloperidol|methadone|amiodarone|sotalol|dofetilide', re.I)
hits={k:mname(v) for k,v in meds.items() if pat.search(mname(v) or '')}
print(len(hits))
c=collections.Counter(hits.values())
for k,v in c.most_common(): print(v,k)
EOF

